contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single test entry: depositAmount used to fund Deposit/receive, collectAmount passed to Collect
    function run(uint depositAmount, uint collectAmount, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Ensure c is initialized with given MinSum and Log file before locking initialization
        // Set MinSum and LogFile only allowed prior to c.Initialized(); do that now
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(0)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // perform a Deposit into c from this contract
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record caller's reported balance before Collect
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        // sanity: beforeBal should reflect depositAmount (but don't assert here; use in rule)

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After the call, read the balance again
        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint curMin = c.MinSum(); if (__ESBMC_reverted()) return;

        // General rule: If Collect reverted, then at least one of the required conditions for Collect
        // must have been false just before the call: balances[this] >= MinSum OR balances[this] >= collectAmount.
        // We express that as: reverted implies (beforeBal < curMin || beforeBal < collectAmount)
        assert(!reverted || (beforeBal < curMin || beforeBal < collectAmount));
    }

    receive() external payable {}
}

